def carregar_prazos(apps, schema_editor):
    from faturamento.management.commands.semear import normalizar
    Convenio = apps.get_model('faturamento', 'Convenio')
    if not Convenio.objects.exists():
        return  # banco novo: o semear cria os convênios e aplica a tabela
    por_nome = {normalizar(c.nome): c for c in Convenio.objects.all()}
    for _, nome, dias in TABELA:
        c = por_nome.get(normalizar(nome))
        if c is None:
            c = Convenio.objects.create(nome=nome)
            por_nome[normalizar(nome)] = c
        c.prazo_operadora = dias
        c.sem_vencimento = dias is None
        c.save()



